18	        BigDecimal amount = invoices.findById(invoiceId).map(Invoice::getAmount)
19	                .orElse(BigDecimal.ZERO);
20	        BigDecimal paid = payments.findByInvoiceIdOrderByIdAsc(invoiceId).stream()
21	                .map(Payment::getAmount)
22	                .reduce(BigDecimal.ZERO, BigDecimal::add);
23	        response.send(new InvoiceDueView(invoiceId, amount, paid, amount.subtract(paid)));
